  const ELEMENT_META={木:{name:'목',icon:'sprout',role:'성장 · 기획',tone:'wood'},火:{name:'화',icon:'sun',role:'표현 · 추진',tone:'fire'},土:{name:'토',icon:'home',role:'안정 · 조율',tone:'earth'},金:{name:'금',icon:'sparkle',role:'판단 · 정리',tone:'metal'},水:{name:'수',icon:'droplet',role:'사고 · 유연',tone:'water'}};
  const RELATION_MOOD={excellent:{icon:'🥕',label:'아주 잘 맞음'},good:{icon:'💗',label:'잘 맞음'},balanced:{icon:'⭐',label:'균형'},caution:{icon:'☁️',label:'차이 있음'},friction:{icon:'🌧️',label:'조율 필요'}};
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
