  function plainLifeText(value,{subject='나'}={}){let out=text(value);const subjectLabel=subject==='나'?'나의':`${honorificName(subject)}의`,replacements=[[/日支\([^)]*\)/g,'가까운 사이에서 반복되는 생활 반응'],[/[子丑寅卯辰巳午未申酉戌亥]\([^)]*\)/g,'각자에게 익숙한 생활 방식'],[/파\([^)]*\)/g,'작은 기대 차이가 쌓이기 쉬운 흐름'],[/[甲乙丙丁戊己庚辛壬癸木火土金水]\([^)]*\)/g,`${subjectLabel} 기본 성향`],[/비견[·ㆍ]?겁재|비겁/g,'자기주도·동료 성향'],[/식신[·ㆍ]?상관|식상/g,'표현·생산 성향'],[/정재[·ㆍ]?편재|재성/g,'현실·자원 관리 성향'],[/정관[·ㆍ]?편관|관성/g,'책임·규칙 성향'],[/정인[·ㆍ]?편인|인성/g,'학습·검토 성향'],[/신강[·ㆍ]?신약|강약 판정/g,'에너지를 쓰는 방식'],[/용신/g,'균형을 위해 보완할 방향'],[/일간/g,`${subjectLabel} 기본 반응`],[/일지-일지/g,'가까운 생활 반응끼리'],[/일지/g,'가까운 관계에서의 생활 반응'],[/십성/g,'생활 역할'],[/원국/g,'타고난 성향 구성'],[/명리(?:학)?/g,'전통 해석'],[/합충형파해/g,'잘 맞거나 부딪히는 전통 관계'],[/A가 B에게 받는 방향/g,'첫 번째 사람이 상대에게서 도움을 받는 방향'],[/B가 A에게 받는 방향/g,'두 번째 사람이 상대에게서 도움을 받는 방향'],[/A의/g,'첫 번째 사람의'],[/B의/g,'두 번째 사람의'],[/파을\/를/g,'작은 생활 어긋남을'],[/이해와 검토을/g,'이해와 검토를'],[/이해와 검토」을/g,'이해와 검토」를'],[/표현과 결과물」를/g,'표현과 결과물」을'],[/대화이/g,'대화가'],[/대화을/g,'대화를'],[/수 있음(?=\s*(패턴|상황))/g,'수 있는'],[/수 있음 상황/g,'수 있는 상황']];for(const [pattern,replacement] of replacements)out=out.replace(pattern,replacement);return out}
  const plainRich=value=>esc(plainLifeText(value)).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
  const teaser=v=>{const value=text(v).replace(/\*\*/g,'').trim();return value.split(/(?<=[.!?。]|다\.)\s+/)[0]||'눌러서 자세히 보기'};
  function readableParagraphs(value,{plain=false,chunk=2}={}){const raw=text(value).trim();if(!raw)return '';const parts=raw.split(/(?<=[.!?。]|다\.)\s+/).filter(Boolean),render=plain?plainRich:rich,html=[];for(let i=0;i<parts.length;i+=chunk)html.push(`<p>${render(parts.slice(i,i+chunk).join(' '))}</p>`);return html.join('')}
  const READING_HIGHLIGHTS=['충분히 이해하고 생각을 정리할 시간','정보를 모으고 검토','전문성·근거를 보강','자기 기준과 자율','표현과 결과물','개인 영역이 존중','최종 결정권과 검토 책임','배경과 이유를 설명','핵심을 빨리 말하고 피드백','연락 빈도와 답장 기준','돈·시간·약속·책임 분담','어디서 편하고, 어디서 반복적으로 엇갈리는지'];
  function autoHighlightRich(raw,limit=2){const matches=READING_HIGHLIGHTS.map(term=>({term,index:raw.indexOf(term)})).filter(row=>row.index>=0).sort((a,b)=>a.index-b.index||b.term.length-a.term.length),selected=[];for(const row of matches){const end=row.index+row.term.length;if(selected.some(item=>row.index<item.end&&end>item.index))continue;selected.push({...row,end});if(selected.length>=limit)break}if(!selected.length)return esc(raw);let cursor=0,html='';selected.sort((a,b)=>a.index-b.index).forEach(row=>{html+=esc(raw.slice(cursor,row.index));html+=`<strong class="reading-highlight">${esc(row.term)}</strong>`;cursor=row.end});return html+esc(raw.slice(cursor))}
  function emphasisRich(value,{plain=false,limit=2,subject='나'}={}){const raw=(plain?plainLifeText(value,{subject}):text(value)).trim();if(!raw)return '';if(raw.includes('**')){let count=0;return esc(raw).replace(/\*\*([^*]+)\*\*/g,(_,term)=>count++<limit?`<strong class="reading-highlight">${term}</strong>`:term)}return autoHighlightRich(raw,limit)}
  function readableEmphasisParagraphs(value,{plain=false,chunk=2,subject='나',limit=2}={}){const raw=text(value).trim();if(!raw)return '';const parts=raw.split(/(?<=[.!?。]|다\.)\s+/).filter(Boolean),html=[];for(let i=0;i<parts.length;i+=chunk)html.push(`<p>${emphasisRich(parts.slice(i,i+chunk).join(' '),{plain,subject,limit})}</p>`);return html.join('')}
  function readingCard(label,value,icon='heart',tone='rose'){const rows=sentences(value);if(!rows.length)return '';return `<article class="reading-card ${tone}"><header><span>${cuteIcon(icon)}</span><h3>${esc(label)}</h3></header>${rows.length>1?`<ul>${rows.map(row=>`<li>${emphasisRich(row,{plain:true})}</li>`).join('')}</ul>`:`<p>${emphasisRich(rows[0],{plain:true})}</p>`}</article>`}
  const list=v=>Array.isArray(v)?v.filter(Boolean):[];
  const sentences=v=>Array.isArray(v)?v.filter(Boolean):text(v)?[text(v)]:[];
  function listHtml(value,cls='insight-list'){const rows=sentences(value);return rows.length?`<ul class="${cls}">${rows.map(x=>`<li>${rich(x)}</li>`).join('')}</ul>`:'<p class="empty-copy">확인된 내용을 정리 중입니다.</p>'}
  function infoCard(label,value,cls=''){const rows=sentences(value);if(!rows.length)return '';return `<article class="detail-box ${cls}"><h3>${esc(label)}</h3>${rows.length>1?listHtml(rows):`<p>${rich(rows[0])}</p>`}</article>`}
  function sourceState(row={}){const status=row.source_status||row,verified=status.verified===true,sourceBacked=status.source_backed===true||String(row.facts?.source||'').startsWith('forceteller');return verified?{tone:'verified',label:'세부 자료까지 확인',description:'연·월·일·시 원국과 오행 계산에 저장된 세부 원국 자료까지 함께 반영했습니다.'}:{tone:'calculated',label:'원국 계산 완료',description:sourceBacked?'연·월·일·시 원국과 오행 계산을 완료했습니다. 일부 보조 세부 항목은 확인 가능한 범위만 반영했습니다.':'연·월·일·시 원국과 오행 계산을 완료했습니다. 외부 세부자료가 없는 항목은 임의로 채우지 않고 확인 가능한 계산값만 반영했습니다.'}}
  function sourceBadge(row={}){const current=sourceState(row);return `<span class="source-badge ${current.tone}" title="${esc(current.description)}">${esc(current.label)}</span>`}
  function sourceDescription(row={}){return sourceState(row).description}
  const PAIR_AXIS_META={element_need:{label:'서로의 부족한 부분을 채워주는 정도',short:'서로 보완',strength:'서로 다른 강점이 필요한 순간에 상대가 자연스럽게 빈틈을 채워줄 수 있어요.',caution:'도움을 주고받는 방향이 한쪽으로 치우치면 한 사람만 계속 맞춰 준다고 느낄 수 있어요.',action:'각자 잘하는 일과 상대에게 도움받고 싶은 일을 구분해서 말해 보세요.'},spouse_palace:{label:'가까워진 뒤 생활 습관이 맞는 정도',short:'가까운 생활',strength:'연락·개인 시간·약속·애정 표현처럼 가까운 사이의 생활 기준이 비교적 자연스럽게 맞는 편이에요.',caution:'가까워질수록 연락 빈도, 개인 시간, 약속 변경, 애정 표현 속도에서 작은 차이가 쌓일 수 있어요.',action:'답장 속도와 혼자 쉬는 시간처럼 반복되는 기준부터 구체적으로 합의해 보세요.'},spouse_star:{label:'연애에서 기대하는 역할이 맞는 정도',short:'연애 기대',strength:'연인에게 기대하는 책임과 역할이 비슷해 상대의 행동을 애정으로 받아들이기 쉬워요.',caution:'한 사람은 책임 있는 행동을, 다른 사람은 빠른 표현을 사랑으로 느끼는 등 기대가 다를 수 있어요.',action:'사랑받는다고 느끼는 행동과 서로 맡고 싶은 책임을 직접 이야기해 보세요.'},stem_daymaster:{label:'기본 반응 속도와 표현 방식',short:'반응 방식',strength:'상황을 받아들이고 반응하는 기본 속도에 공통점이 있어 첫 대화가 잘 통할 수 있어요.',caution:'같은 일을 보고도 결론을 내리는 속도와 표현 강도가 달라 오해가 생길 수 있어요.',action:'결론이 필요한 시점과 필요한 설명의 양을 먼저 맞춰 보세요.'},stem_communication:{label:'생각을 말로 주고받는 방식',short:'대화 호흡',strength:'생각을 꺼내는 순서와 반응 속도가 비슷해 의견을 주고받기 쉬운 편이에요.',caution:'한 사람은 충분한 설명을, 다른 사람은 빠른 결론을 원하면 대화가 엇갈릴 수 있어요.',action:'먼저 결론을 말할지, 배경부터 설명할지 대화 순서를 정해 보세요.'},friend_ten_gods:{label:'친구로서 맡기 쉬운 역할의 조화',short:'친구 역할',strength:'함께할 때 각자 맡기 쉬운 역할이 달라 협력 관계로 이어지기 좋아요.',caution:'조언·실행·정리 역할이 한쪽에만 쏠리면 관계가 부담으로 느껴질 수 있어요.',action:'도움을 줄 때는 상대가 원하는 것이 조언인지 공감인지 먼저 물어보세요.'},branch_network:{label:'여러 생활 장면에서 자연스럽게 어울리는 정도',short:'일상 호흡',strength:'데이트·약속·주변 사람과의 만남처럼 여러 생활 장면에서 자연스럽게 맞춰지는 부분이 많은 편이에요.',caution:'특정 장면에서는 잘 맞아도 다른 생활 영역에서는 반복적으로 부딪힐 수 있어요.',action:'편한 날뿐 아니라 피곤할 때와 일정이 바뀔 때의 반응도 함께 살펴보세요.'},month_life:{label:'사회생활과 일상 리듬이 맞는 정도',short:'생활 리듬',strength:'일정·일하는 방식·사회생활 리듬이 비슷해 함께 계획을 세우기 쉬운 편이에요.',caution:'바쁜 시기의 연락 방식이나 쉬는 시간, 사람을 만나는 빈도는 저절로 맞지 않을 수 있어요.',action:'평일·주말·바쁜 기간의 연락과 만남 기준을 나누어 정해 보세요.'},month_social:{label:'모임과 사회생활에서 맞는 속도',short:'모임 리듬',strength:'모임·일·친구 관계에서 사람을 대하는 속도가 비슷해 함께 움직이기 쉬워요.',caution:'사람을 만나는 빈도나 일과 사생활을 나누는 기준은 다를 수 있어요.',action:'함께할 모임과 각자 보낼 시간을 미리 나누어 보세요.'},conflict_buffer:{label:'갈등이 생겨도 다시 풀어갈 여지',short:'갈등 회복',strength:'의견이 달라도 관계를 끊기보다 다시 대화하며 풀어갈 여지가 있는 편이에요.',caution:'갈등이 커지면 감정을 낮춰 줄 공통 규칙이 부족해 같은 싸움이 길어질 수 있어요.',action:'싸운 뒤 언제 다시 이야기할지와 사과·수정 순서를 미리 정해 두세요.'}};
  function pairAxisMeta(axis={}){return PAIR_AXIS_META[axis.key]||{label:'두 사람의 관계 흐름',short:'관계 흐름',strength:'서로 편하게 맞춰지는 장면이 있습니다.',caution:'상황에 따라 반응 차이를 느낄 수 있습니다.',action:'실제 생활에서 같은 장면이 반복되는지 확인해 보세요.'}}
  function axisPlainCopy(axis={}){const score=Math.max(0,Math.min(100,Number(axis.score)||0)),meta=pairAxisMeta(axis);return score>=75?`이 부분은 두 사람이 비교적 편안하게 맞는 편이에요. ${meta.strength}`:score>=60?`잘 맞는 부분과 차이가 함께 있는 영역이에요. ${meta.strength} 다만 ${meta.caution}`:`저절로 맞기보다 말로 기준을 정해야 편해지는 영역이에요. ${meta.caution}`}
  function axisTechnicalText(value){return plainLifeText(value).replace(/긍정 관계/g,'서로 돕는 관계').replace(/주의 관계/g,'엇갈릴 수 있는 관계').replace(/완충 신호/g,'갈등을 낮추는 요소').replace(/긴장 신호/g,'갈등을 키울 수 있는 요소').replace(/천간합/g,'표현이 자연스럽게 이어지는 관계').replace(/상극 계열/g,'표현이 부딪힐 수 있는 관계')}
  function axisCards(axes,limit=99){return `<div class="axis-grid plain-axis-grid">${list(axes).slice(0,limit).map(axis=>{const score=Math.max(0,Math.min(100,Number(axis.score)||0)),meta=pairAxisMeta(axis),technical=text(axis.summary||axis.explanation);return `<article class="axis-card plain-axis-card"><div class="axis-head"><strong>${esc(meta.label)}</strong><span>${Math.round(score)}점</span></div><div class="axis-track"><span style="width:${score}%"></span></div><p>${esc(axisPlainCopy(axis))}</p><div class="axis-life-tip"><strong>생활에서 확인할 점</strong><p>${esc(meta.action)}</p></div>${technical||list(axis.evidence).length?`<details class="axis-technical-details"><summary>계산 용어와 근거 보기</summary><div><small>전통 계산 항목</small><strong>${esc(axis.label||axis.key)}</strong>${technical?`<p>${esc(axisTechnicalText(technical))}</p>`:''}${list(axis.evidence).map(e=>`<p><b>${esc(e.title||e.category)}</b> ${esc(axisTechnicalText(e.detail||''))}</p>`).join('')}</div></details>`:''}</article>`}).join('')}</div>`}
  const show=(el,on=true)=>el&&el.classList.toggle('hidden',!on);
  function toast(message,{actionLabel='',onAction=null,duration=3500}={}){const box=$('#toast');clearTimeout(toast.timer);box.replaceChildren();const copy=document.createElement('span');copy.textContent=message;box.append(copy);if(actionLabel&&typeof onAction==='function'){const action=document.createElement('button');action.type='button';action.className='toast-action';action.textContent=actionLabel;action.onclick=()=>{clearTimeout(toast.timer);show(box,false);onAction()};box.append(action)}show(box,true);toast.timer=setTimeout(()=>show(box,false),duration)}
  function setInputBackMode(returnToReport=false){state.editingFromReport=Boolean(returnToReport&&state.result);const button=$('#inputBackButton'),label=$('#inputBackLabel');const message=state.editingFromReport?'기존 리포트로 돌아가기':'시작 화면으로 돌아가기';if(button){button.setAttribute('aria-label',message);button.title=message;button.classList.toggle('returns-to-report',state.editingFromReport)}if(label)label.textContent=state.editingFromReport?'기존 리포트':'시작 화면'}
  function showIntroScreen(){setInputBackMode(false);show($('#introSplash'),true);show($('#onboarding'),false);show($('#workspace'),false);document.body.classList.add('intro-active')}
  function showInputScreen({fromReport=false}={}){if(fromReport&&state.result)state.reportReturnPage=state.activePage||'profile';setInputBackMode(fromReport);show($('#introSplash'),false);show($('#onboarding'),true);show($('#workspace'),false);document.body.classList.remove('intro-active');scrollTo({top:0,behavior:'smooth'})}
  function returnFromInput(){if(state.editingFromReport&&state.result){const page=state.reportReturnPage||'profile';setInputBackMode(false);showWorkspace();switchPage(page);return}showIntroScreen()}
  function showWorkspace(){show($('#introSplash'),false);show($('#onboarding'),false);show($('#workspace'),true);document.body.classList.remove('intro-active');scrollTo({top:0,behavior:'smooth'})}
  async function api(path,options={}){const res=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const body=await res.json().catch(()=>({ok:false,error:'서버 응답을 읽지 못했습니다.'}));if(!res.ok||body.ok===false)throw new Error(body.error||'요청을 처리하지 못했습니다.');return body.data}
  function parseDate(value){const digits=String(value||'').replace(/\D/g,'');if(digits.length!==8)return null;const y=+digits.slice(0,4),m=+digits.slice(4,6),d=+digits.slice(6,8),dt=new Date(y,m-1,d);return dt.getFullYear()===y&&dt.getMonth()===m-1&&dt.getDate()===d?{year:y,month:m,day:d}:null}
  function parseTime(value){const digits=String(value||'').replace(/\D/g,'');if(!digits)return null;const padded=digits.length<=2?digits.padStart(2,'0')+'00':digits.padStart(4,'0');const hour=+padded.slice(0,2),minute=+padded.slice(2,4);return hour<24&&minute<60?{hour,minute}:null}
  function syncMainInputs(){const form=$('#profileForm'),d=parseDate($('[data-birth-text="main"]')?.value),unknown=form.elements.time_unknown.checked,t=unknown?{hour:0,minute:0}:parseTime($('[data-time-text="main"]')?.value);if(d){form.elements.year.value=d.year;form.elements.month.value=d.month;form.elements.day.value=d.day}if(t){form.elements.hour.value=t.hour;form.elements.minute.value=t.minute}return {d,t,unknown}}
  function validateVisibleForm(form=$('#profileForm')){const {d,t,unknown}=syncMainInputs();$$('.field-error',form).forEach(e=>show(e,false));let target=null,message='';if(!d){const e=$('[data-error-for="main-birth"]');e.textContent='생년월일을 8자리로 정확히 입력해 주세요.';show(e,true);target=$('[data-birth-text="main"]');message=e.textContent}else if(!unknown&&!t){const e=$('[data-error-for="main-time"]');e.textContent='출생시간을 24시간제로 입력하거나 ‘시간을 몰라요’를 선택해 주세요.';show(e,true);target=$('[data-time-text="main"]');message=e.textContent}else if(!form.checkValidity()){target=$(':invalid',form);message='필수 입력값을 확인해 주세요.'}if(target){toast(message);target.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>target.focus({preventScroll:true}),350);return false}return true}
  function mainProfile(){const f=$('#profileForm'),fd=new FormData(f),unknown=f.elements.time_unknown.checked;return {name:String(fd.get('name')||'나').trim(),gender:fd.get('gender'),calendar_type:fd.get('calendar_type'),is_leap_month:fd.get('is_leap_month')==='true',year:+fd.get('year'),month:+fd.get('month'),day:+fd.get('day'),hour:unknown?0:+fd.get('hour'),minute:unknown?0:+fd.get('minute'),time_known:!unknown,country_code:fd.get('country_code'),country:fd.get('country_custom')||'',city:fd.get('city')||'',partner_gender:fd.get('partner_gender')||'M'} }
  function bindTimeUnknown(root=document){$$('[data-time-block]',root).forEach(block=>{$$('.time-choice-button',block).forEach(btn=>btn.addEventListener('click',()=>{const unknown=btn.dataset.timeSet==='unknown';$$('.time-choice-button',block).forEach(x=>x.classList.toggle('active',x===btn));const check=$('input[type="checkbox"]',block);if(check)check.checked=unknown;show($('[data-time-inputs-for]',block),!unknown);show($('.time-unknown-message',block),unknown)}))})}
  function bindCalendarControls(root=document){$$('select[name="calendar_type"]',root).forEach(sel=>sel.addEventListener('change',()=>{const scope=sel.closest('.form-grid')||sel.parentElement.parentElement;show($('.leap-field',scope),sel.value==='lunar')}))}
  function bindCountryControls(root=document){$$('.country-select',root).forEach(sel=>sel.addEventListener('change',()=>{const scope=sel.closest('.form-grid')||root;const foreign=sel.value!=='KR';show($('.other-country',scope),sel.value==='OTHER');show($('.foreign-city',scope),foreign)}))}
  function bindBirthPickers(root=document){$$('[data-open-birth-picker]',root).forEach(btn=>btn.addEventListener('click',()=>{const key=btn.dataset.openBirthPicker,panel=$(`[data-birth-picker-panel="${key}"]`);if(!panel)return;const parsed=parseDate($(`[data-birth-text="${key}"]`)?.value)||{year:2000,month:1,day:1};panel.dataset.month=parsed.month;panel.dataset.day=parsed.day;$('[data-picker-year]',panel).value=parsed.year;renderPicker(panel,key);show(panel,true)}));$$('[data-close-birth-picker]',root).forEach(b=>b.addEventListener('click',()=>show(b.closest('.birth-picker-modal'),false)));$$('[data-year-step]',root).forEach(b=>b.addEventListener('click',()=>{const panel=b.closest('.birth-picker-panel'),input=$('[data-picker-year]',panel);input.value=Math.max(1900,Math.min(2100,(+input.value||2000)+(+b.dataset.yearStep)))}));$$('[data-confirm-birth-picker]',root).forEach(b=>b.addEventListener('click',()=>{const modal=b.closest('.birth-picker-modal'),key=b.dataset.confirmBirthPicker,y=+$('[data-picker-year]',modal).value,m=+modal.dataset.month,d=+modal.dataset.day;$(`[data-birth-text="${key}"]`).value=`${y}.${String(m).padStart(2,'0')}.${String(d).padStart(2,'0')}`;show(modal,false);syncMainInputs()}))}
  function renderPicker(modal,key){const months=$('[data-picker-months]',modal),days=$('[data-picker-days]',modal);months.innerHTML=Array.from({length:12},(_,i)=>`<button type="button" data-month="${i+1}">${i+1}월</button>`).join('');const y=+$('[data-picker-year]',modal).value||2000,m=+modal.dataset.month||1,max=new Date(y,m,0).getDate();days.innerHTML=Array.from({length:max},(_,i)=>`<button type="button" data-day="${i+1}">${i+1}</button>`).join('');$$('[data-month]',months).forEach(b=>b.onclick=()=>{modal.dataset.month=b.dataset.month;renderPicker(modal,key)});$$('[data-day]',days).forEach(b=>b.onclick=()=>{modal.dataset.day=b.dataset.day;$$('[data-day]',days).forEach(x=>x.style.background=x===b?'#eee9ff':'#fff')})}
  function personFields(prefix,label='상대방',{removable=false}={}){const head=removable?`<div class="dynamic-person-head"><strong data-member-title>${esc(label)}</strong><button class="member-remove-button" type="button" data-remove-member aria-label="${esc(label)} 삭제"><span aria-hidden="true">×</span>삭제</button></div>`:'';return `<div class="dynamic-person form-grid" data-person-prefix="${esc(prefix)}">${head}<label>이름<input name="${prefix}_name" required placeholder="${esc(label)} 이름"></label><label>성별<select name="${prefix}_gender"><option value="F">여성</option><option value="M">남성</option></select></label><label>양력/음력<select name="${prefix}_calendar_type"><option value="solar">양력</option><option value="lunar">음력</option></select></label><label class="leap-field hidden" data-leap-for="${prefix}">윤달<select name="${prefix}_is_leap_month"><option value="false">평달</option><option value="true">윤달</option></select></label><label>생년월일<input name="${prefix}_birth" placeholder="1990.01.01" required></label><label>출생시간<input name="${prefix}_time" placeholder="12:00"></label><label>출생 국가<select name="${prefix}_country_code" class="country-select"><option value="KR">대한민국</option></select></label></div>`}
  function memberAddButton(attribute){return `<div class="member-add-row"><button type="button" class="ghost-button member-add-button" ${attribute}><span class="member-add-bunny" aria-hidden="true"><b>＋</b></span><span class="member-add-copy"><strong>구성원 추가</strong><small>새 사람의 출생정보를 입력해요</small></span><span class="member-add-arrow" aria-hidden="true">→</span></button></div>`}
  function nextMemberNumber(root,stem){pruneMemberUndoHistory();const prefixes=[...$$('.dynamic-person',root).map(card=>card.dataset.personPrefix||''),...memberUndoHistory.map(item=>item.card.dataset.personPrefix||'')],numbers=prefixes.filter(prefix=>prefix.startsWith(stem)).map(prefix=>Number(prefix.slice(stem.length))||0);return Math.max(0,...numbers)+1}
  function refreshMemberLabels(root){$$('.dynamic-person',root).forEach((card,i)=>{const label=`구성원 ${i+1}`,title=$('[data-member-title]',card),remove=$('[data-remove-member]',card);if(title)title.textContent=label;if(remove)remove.setAttribute('aria-label',`${label} 삭제`)})}
  function pruneMemberUndoHistory(){for(let i=memberUndoHistory.length-1;i>=0;i--){const item=memberUndoHistory[i];if(!item.parent.isConnected||item.card.isConnected)memberUndoHistory.splice(i,1)}return memberUndoHistory.length}
  function showMemberUndoToast(message='구성원을 삭제했습니다.'){const count=pruneMemberUndoHistory();if(!count){toast(message);return}const copy=count>1?`${message} 최근 삭제부터 ${count}건을 되돌릴 수 있어요.`:message;toast(copy,{actionLabel:count>1?`되돌리기 (${count})`:'되돌리기',duration:8000,onAction:undoLastMemberRemoval})}
  function undoLastMemberRemoval(){pruneMemberUndoHistory();const item=memberUndoHistory.pop();if(!item)return;const {card,parent,next,index,root,minimum,onChange}=item,positionAnchor=$$('.dynamic-person',parent)[index]||null;parent.insertBefore(card,next?.parentElement===parent?next:positionAnchor);refreshMemberLabels(root);bindMemberRemoval(root,{minimum,onChange});onChange();card.scrollIntoView({behavior:'smooth',block:'nearest'});const remaining=pruneMemberUndoHistory();if(remaining)showMemberUndoToast(`구성원을 복구했습니다. 이전 삭제 ${remaining}건이 남아 있어요.`);else toast('삭제한 구성원을 다시 복구했습니다.')}
  function bindMemberRemoval(root,{minimum=1,onChange=()=>{}}={}){$$('[data-remove-member]',root).forEach(button=>{button.onclick=()=>{const cards=$$('.dynamic-person',root);if(cards.length<=minimum){toast('그룹에는 나를 제외하고 최소 한 명이 필요해요.');return}const card=button.closest('.dynamic-person'),next=card?.nextElementSibling,parent=card?.parentElement,index=cards.indexOf(card);if(!card||!parent)return;card.remove();memberUndoHistory.push({card,parent,next,index,root,minimum,onChange});refreshMemberLabels(root);onChange();showMemberUndoToast()}})}
  function memberProfiles(fd,root){return $$('.dynamic-person',root).map(card=>profileFromPrefix(fd,card.dataset.personPrefix))}
  function profileFromPrefix(fd,prefix){const d=parseDate(fd.get(`${prefix}_birth`)),t=parseTime(fd.get(`${prefix}_time`));if(!d)throw new Error('추가한 사람의 생년월일을 확인해 주세요.');return {name:String(fd.get(`${prefix}_name`)||'상대').trim(),gender:fd.get(`${prefix}_gender`),calendar_type:fd.get(`${prefix}_calendar_type`),is_leap_month:fd.get(`${prefix}_is_leap_month`)==='true',...d,hour:t?.hour||0,minute:t?.minute||0,time_known:!!t,country_code:fd.get(`${prefix}_country_code`)||'KR',country:'',city:''}}
  function updateOptions(){const f=$('#profileForm'),match=f.elements.build_matches.checked,pair=f.elements.include_pair.checked,group=f.elements.include_group.checked;$$('.option-card',f).forEach(x=>x.classList.toggle('selected',$('input',x).checked));show($('#matchOptionFields'),match);const pairRoot=$('#initialPairFields'),groupRoot=$('#initialGroupFields');show(pairRoot,pair);show(groupRoot,group);if(pair&&!pairRoot.innerHTML)pairRoot.innerHTML=`<h3>함께 볼 한 사람</h3>${personFields('pair','상대방')}<label class="compact-label">관계 유형<select name="pair_mode"><option value="love">연인</option><option value="friend">친구</option></select></label>`;if(group&&!groupRoot.innerHTML)groupRoot.innerHTML=`<h3>함께 볼 그룹</h3><label class="compact-label">그룹 유형<select name="group_context"><option value="friends">친구</option><option value="work">직장·프로젝트</option><option value="family">가족</option><option value="hobby">취미 모임</option></select></label><div data-initial-members>${personFields('member1','멤버 1',{removable:true})}${personFields('member2','멤버 2',{removable:true})}</div>${memberAddButton('data-add-initial-member')}`;$$('input,select',pairRoot).forEach(x=>x.disabled=!pair);$$('input,select',groupRoot).forEach(x=>x.disabled=!group);bindCalendarControls(f);bindCountryControls(f);refreshMemberLabels(groupRoot);bindMemberRemoval(groupRoot,{onChange:updateEstimate});const addButton=$('[data-add-initial-member]');if(addButton)addButton.onclick=addInitialMember;updateEstimate()}
  function addInitialMember(){const root=$('[data-initial-members]'),n=nextMemberNumber(root,'member');root.insertAdjacentHTML('beforeend',personFields(`member${n}`,`구성원 ${$$('.dynamic-person',root).length+1}`,{removable:true}));const card=root.lastElementChild;bindCalendarControls(card);bindCountryControls(card);refreshMemberLabels(root);bindMemberRemoval(root,{onChange:updateEstimate});updateEstimate()}
  function summaryForEstimate(){const f=$('#profileForm'),groupExtra=f.elements.include_group.checked?$$('.dynamic-person',$('#initialGroupFields')).length:0;return {birth_year:Number(f.elements.year.value||new Date().getFullYear()),build_matches:f.elements.build_matches.checked,include_pair:f.elements.include_pair.checked,group_members:groupExtra?groupExtra+1:0}}
  function durationUnitText(value){const sec=Math.max(1,Math.round(Number(value)||0));if(sec<60)return `${sec}초`;const minutes=Math.floor(sec/60),rest=sec%60;return rest?`${minutes}분 ${rest}초`:`${minutes}분`}
  function durationEstimateText(value){return `약 ${durationUnitText(value)}`}
  function durationEstimateRange(value){if(value&&typeof value==='object'){const center=Number(value.seconds),low=Number(value.min),high=Number(value.max);if(low>0&&high>low)return `약 ${durationUnitText(low)}~${durationUnitText(high)}`;if(center>0)return durationEstimateText(center)}const seconds=Number(value);return seconds>0?durationEstimateText(seconds):'분석 범위에 따라 계산 중…'}
  async function updateEstimate(){syncMainInputs();const summary=summaryForEstimate();const items=['내 사주','운세'];if(summary.build_matches)items.push('잘 맞는 사람');if(summary.include_pair)items.push('1:1 궁합');if(summary.group_members>=2)items.push(`그룹 궁합 ${summary.group_members}명`);$('#analysisSummaryText').textContent=items.join(' · ');try{const d=await api('/api/progress/estimate',{method:'POST',body:JSON.stringify({kind:'initial',summary})});$('#estimatedTimeText').textContent=durationEstimateRange(d.expected_seconds??d.estimated_seconds??d.seconds)}catch{$('#estimatedTimeText').textContent='분석 범위에 따라 달라져요.'}}
  function loading(open=true){show($('#loading'),open);if(!open){clearInterval(state.poll);state.poll=null;state.jobId=null}}
  function updateProgress(d={}){const rawPercent=d.percent??((d.progress??d.fraction??0)*100),percent=Math.max(0,Math.min(100,Math.round(rawPercent))),stage=$('#loadingStage'),track=$('.loading-progress-track');$('#loadingProgressFill').style.width=`${percent}%`;$('#loadingPercent').textContent=`${percent}%`;stage.textContent=d.message||d.stage_label||'차근차근 분석하고 있어요';track?.setAttribute('aria-valuenow',String(percent));const remaining=typeof d.remaining_seconds==='object'?d.remaining_seconds?.seconds:d.remaining_seconds;if(remaining!=null)$('#loadingRemaining').textContent=durationEstimateText(remaining);else if(d.remaining_seconds?.state==='recalculating')$('#loadingRemaining').textContent='다시 계산 중';const fallback=['출생정보 확인','원국 구성','생활 해석','관계 분석','리포트 정리'].map((label,i)=>({label,status:percent>=(i+1)*20?'done':percent>=i*20?'active':'pending',fraction:Math.max(0,Math.min(1,(percent-i*20)/20))})),steps=list(d.steps).length?list(d.steps):fallback;$('#loadingSteps').innerHTML=steps.map((step,i)=>{const status=step.status||'pending',value=status==='done'?100:Math.round((Number(step.fraction)||0)*100),stateLabel=status==='done'?'완료':status==='active'?'진행 중':status==='cancelled'?'중단됨':'대기';return `<div class="loading-step ${esc(status)}"><span class="loading-step-index">${status==='done'?'✓':i+1}</span><span class="loading-step-copy"><strong>${esc(step.label||`분석 단계 ${i+1}`)}</strong><small>${stateLabel}</small></span><b>${status==='pending'?'—':`${value}%`}</b></div>`}).join('')}
  async function postWithProgress(kind,path,payload,summary={}){const job=await api('/api/progress/start',{method:'POST',body:JSON.stringify({kind,summary})});state.jobId=job.id||job.job_id;state.startedAt=Date.now();loading(true);updateProgress(job);state.poll=setInterval(async()=>{if(!state.jobId)return;try{updateProgress(await api(`/api/progress/${state.jobId}`))}catch{}},650);try{return await api(path,{method:'POST',body:JSON.stringify({...payload,job_id:state.jobId})})}finally{const remaining=MINIMUM_LOADING_MS-(Date.now()-state.startedAt);if(remaining>0)await new Promise(resolve=>setTimeout(resolve,remaining));loading(false)}}
  async function cancelActiveRequest(){if(!state.jobId)return;try{await api(`/api/progress/${state.jobId}/cancel`,{method:'POST',body:'{}'});toast('분석 중단을 요청했습니다.')}catch(e){toast(e.message)}}
  async function submitInitial(e){e.preventDefault();if(!validateVisibleForm())return;const f=e.currentTarget,fd=new FormData(f),profile=mainProfile(),button=$('#createReportButton'),label=$('.compact-submit-label',button);let pair_request=null,group_request=null;try{if(f.elements.include_pair.checked)pair_request={mode:fd.get('pair_mode'),target:profileFromPrefix(fd,'pair')};if(f.elements.include_group.checked){const members=memberProfiles(fd,$('#initialGroupFields'));group_request={context:fd.get('group_context'),members}}}catch(err){toast(err.message);return}const payload={profile,build_matches:f.elements.build_matches.checked,pair_request,group_request,ai_cache_only:document.body.dataset.testMode==='true'};button.disabled=true;button.classList.add('is-loading');if(label)label.textContent='리포트 준비 중…';try{state.profile=profile;state.result=await postWithProgress('initial','/api/initial',payload,summaryForEstimate());setInputBackMode(false);renderAll();showWorkspace()}catch(err){toast(err.message)}finally{button.disabled=false;button.classList.remove('is-loading');if(label)label.textContent='리포트 시작하기'}}
  function sectionIcon(title=''){if(/잘 맞는 사람|자연스러운|강점/.test(title))return 'carrot';if(/조율|미리 확인|주의/.test(title))return 'cloud';if(/궁합|관계|사람/.test(title))return 'heart';if(/운세|올해|대운|흐름/.test(title))return 'rainbow';if(/원국|사주|해석|근거|구성/.test(title))return 'sparkle';return 'star'}
  function section(title,body,cls=''){return `<section class="section-card card ${cls}"><h2><span class="section-title-icon">${cuteIcon(sectionIcon(title))}</span>${esc(title)}</h2>${body}</section>`}
  function tags(rows){return `<div class="tag-list">${list(rows).map(x=>`<span class="tag">${esc(typeof x==='string'?x:(x.label||x.title||x.keyword))}</span>`).join('')}</div>`}
  function pillarMeta(value){const p=String(value||'');if(p.length<2)return {reading:'미확정',elements:'출생정보 확인 필요'};return {reading:`${STEM_READING[p[0]]||p[0]}${BRANCH_READING[p[1]]||p[1]}주`,elements:`천간 ${STEM_ELEMENT[p[0]]||'미정'} · 지지 ${BRANCH_ELEMENT[p[1]]||'미정'}`}}
  function elementVisual(key=''){return {목:{tone:'wood',name:'목',icon:'sprout'},화:{tone:'fire',name:'화',icon:'sun'},토:{tone:'earth',name:'토',icon:'home'},금:{tone:'metal',name:'금',icon:'sparkle'},수:{tone:'water',name:'수',icon:'droplet'}}[key]||{tone:'neutral',name:'미정',icon:'star'}}
  function periodPillarVisual(value='',compact=false){const pillar=String(value||''),stem=pillar[0]||'',branch=pillar[1]||'';if(!stem||!branch)return `<span class="period-pillar-visual missing"><strong>—</strong><small>간지 확인 필요</small></span>`;const stemElement=STEM_ELEMENT[stem],branchElement=BRANCH_ELEMENT[branch],stemVisual=elementVisual(stemElement),branchVisual=elementVisual(branchElement),label=`${STEM_READING[stem]||stem}${stemElement}, ${BRANCH_READING[branch]||branch}${branchElement}`;return `<span class="period-pillar-visual ${compact?'compact':''}" aria-label="${esc(label)}"><span class="period-character ${stemVisual.tone}"><small>천간 · ${esc(stemElement)}</small><strong>${esc(stem)}</strong><em>${esc(STEM_READING[stem]||'')}</em></span><i aria-hidden="true">+</i><span class="period-character ${branchVisual.tone}"><small>지지 · ${esc(branchElement)}</small><strong>${esc(branch)}</strong><em>${esc(BRANCH_READING[branch]||'')}</em></span></span>`}
  function pillarPart(char='',position='stem'){const element=position==='stem'?STEM_ELEMENT[char]:BRANCH_ELEMENT[char],visual=elementVisual(element),reading=position==='stem'?STEM_READING[char]:BRANCH_READING[char];return `<div class="pillar-part ${position} ${visual.tone}"><span>${cuteIcon(visual.icon)}</span><small>${position==='stem'?'천간':'지지'} · ${esc(visual.name)}</small><strong>${esc(char||'—')}</strong><em>${esc(reading||'미정')}</em></div>`}
  function pillarCard(label,value,detail={}){const raw=String(value||''),meta=pillarMeta(raw),isDay=detail.key==='day'||label.startsWith('일주'),icon=isDay?'bunny':detail.key==='hour'||label.startsWith('시주')?'moon':detail.key==='month'||label.startsWith('월주')?'rainbow':'home',valid=raw.length===2;return `<article class="pillar-card natal-pillar-card ${isDay?'day-pillar':''} ${valid?'':'missing'}"><header><span class="pillar-cute-icon">${cuteIcon(icon)}</span><div><small>${esc(label)}</small><strong>${isDay?'나의 중심 기둥':esc(meta.reading)}</strong></div>${isDay?'<b>중심</b>':''}</header>${valid?`<div class="pillar-pair-board" aria-label="${esc(raw)}">${pillarPart(raw[0],'stem')}<div class="pillar-flow" aria-hidden="true"><i></i><span>위</span><i></i></div>${pillarPart(raw[1],'branch')}</div>`:'<div class="pillar-empty"><strong>시주 미확정</strong><small>출생시간을 임의로 넣지 않았어요.</small></div>'}<p>${rich(detail.life_scope||detail.meaning||'이 기둥이 담당하는 생활 영역을 전체 원국과 함께 봅니다.')}</p></article>`}
  function reportNatalChart(facts,detail={},label=''){const c=facts?.chart||{},rows=Object.fromEntries(list(detail.pillars).map(x=>[x.key,x]));return `<div class="natal-board ${label?'comparison-natal-board':''}"><div class="natal-board-guide"><div><strong>${esc(label||'위는 천간, 아래는 지지')}</strong><small>${label?'내 원국과 같은 방식으로 위 천간·아래 지지, 오행 색을 읽어요.':'글자색은 오행을 뜻하고 일주는 나의 중심으로 강조했어요.'}</small></div><div class="element-legend"><span class="wood">목</span><span class="fire">화</span><span class="earth">토</span><span class="metal">금</span><span class="water">수</span></div></div><div class="pillar-grid natal-pillar-grid">${pillarCard('시주 · 장기 관심',facts?.profile?.time_known?c.hour_pillar:'',rows.hour||{})}${pillarCard('일주 · 나의 중심',c.day_pillar,rows.day||{key:'day'})}${pillarCard('월주 · 사회와 계절',c.month_pillar,rows.month||{})}${pillarCard('연주 · 초기 환경',c.year_pillar,rows.year||{})}</div></div>`}
  function elementOverview(profile={},facts={}){const supplied=Object.fromEntries(list(profile.elements).map(x=>[x.element,x])),fallback=facts.element_percent||{},useful=new Set(list(facts.useful_elements).map(String));return `<div class="element-overview"><div class="overview-heading"><div><span class="eyebrow">FIVE ELEMENTS</span><h3>내 오행 균형</h3></div><p>다섯 기운의 비율과 역할을 차분하게 비교해 보세요.</p></div><div class="element-wheel">${Object.entries(ELEMENT_META).map(([key,meta])=>{const row=supplied[key]||{},value=Math.max(0,Math.min(100,Number(row.percent??fallback[key]??0))),stateLabel=row.state||(value>=30?'강하게 드러남':value>=15?'고르게 있음':value>0?'보완하면 좋음':'부족한 편');return `<article class="element-tile ${meta.tone} ${useful.has(key)?'useful':''}"><div class="element-symbol"><span>${cuteIcon(meta.icon)}</span><strong>${key}</strong></div><div class="element-name"><h4>${meta.name}</h4><small>${meta.role}</small></div><b>${value.toFixed(1)}%</b><div class="element-track"><span style="width:${value}%"></span></div><p>${esc(stateLabel)}</p>${useful.has(key)?'<em>균형 도움</em>':''}</article>`}).join('')}</div></div>`}
  function natalInline(facts){const c=facts?.chart||{},ordered=[c.hour_pillar,c.day_pillar,c.month_pillar,c.year_pillar];return ordered.map(x=>{const meta=pillarMeta(x);return `${esc(x||'—')} <small>${esc(meta.reading)}</small>`}).join(' <span aria-hidden="true">·</span> ')}
  function chartDetailHtml(detail={}){const intro=detail.intro||{},balance=detail.balance||{},relations=list(detail.relations),elements=detail.element_context||{};return `<div class="chart-deep"><div class="explanation-lead"><h3>${esc(intro.title||'네 기둥이 맡는 역할을 함께 봅니다.')}</h3><p>${rich(intro.text||'일주를 중심으로 월주·연주·시주가 어떤 생활 영역을 더하는지 살펴봅니다.')}</p></div><div class="pillar-detail-grid">${list(detail.pillars).map(p=>`<article class="explanation-card"><div class="explanation-card-head"><span>${esc(p.label)}</span><strong>${esc(p.pillar||'미확정')}</strong><em>${esc(p.reading||'')}</em></div><p>${rich(p.life_scope||'')}</p>${p.outer?`<p>${rich(p.outer)}</p>`:''}${p.foundation?`<p>${rich(p.foundation)}</p>`:''}<small>${esc(p.evidence||'')}</small></article>`).join('')}</div><h3>계절·강약·균형을 생활 언어로 보면</h3><div class="explanation-grid">${infoCard('태어난 계절의 배경',balance.season)}${infoCard('내 중심 기운의 힘',balance.strength)}${infoCard('균형을 돕는 방향',balance.useful)}</div>${elements.summary?`<div class="notice"><strong>오행 비율을 읽는 방법</strong><p>${rich(elements.summary)}</p><small>${esc(elements.evidence||'')}</small></div>`:''}${relations.length?`<h3>원국 안에서 반복되는 연결</h3><div class="explanation-grid">${relations.map(x=>infoCard(x.title,x.meaning)).join('')}</div>`:''}</div>`}
  function profileKeyPointBoard(points=[]){const rows=list(points).slice(0,4);return rows.length?`<div class="plain-key-grid">${rows.map((row,i)=>`<article><span>0${i+1}</span><h3>${esc(row.title||'나를 이해하는 기준')}</h3><p>${plainRich(row.meaning||row.summary||'')}</p></article>`).join('')}</div>`:'<p class="empty-copy">핵심 성향을 생활 언어로 정리하고 있습니다.</p>'}
  function domainCardHtml(key,profile={}){const meta=DOMAIN_META[key]||{icon:'star',title:domainLabels[key]||key,question:'생활에서 어떻게 나타날까요?',tone:'violet'},dimensions=list(profile[`${key}_dimensions`]),preview=dimensions[0]?.assessment||profile[key];return `<article class="life-domain-card ${meta.tone}"><button type="button" data-domain="${key}"><span class="life-domain-icon">${cuteIcon(meta.icon)}</span><span class="life-domain-kicker">${esc(meta.question)}</span><h3>${esc(meta.title)}</h3><p>${plainRich(teaser(preview||'분석 내용을 정리하고 있습니다.'))}</p><span class="card-link">자세히 살펴보기 →</span></button></article>`}
  function profileDomainDetail(key,value,profile={}){const meta=DOMAIN_META[key]||{icon:'star',title:domainLabels[key]||key,question:'생활에서 어떻게 나타날까요?',tone:'violet'},dimensions=list(profile[`${key}_dimensions`]),deep=profile.deep_synthesis?.[key];return `<div class="life-detail-head ${meta.tone}"><span class="life-domain-icon">${cuteIcon(meta.icon)}</span><div><span class="eyebrow">${esc(meta.question)}</span><h3>${esc(meta.title)}</h3></div></div><div class="domain-lead">${readableParagraphs(value||'분석 내용을 준비하고 있습니다.',{plain:true,chunk:2})}</div>${deep?`<div class="plain-summary"><strong>핵심만 정리하면</strong>${readableParagraphs(deep,{plain:true,chunk:2})}</div>`:''}${dimensions.length?`<div class="dimension-grid plain-dimensions">${dimensions.map(row=>`<article><span>확인할 포인트</span><h4>${esc(row.title||row.label||'생활 장면')}</h4><p>${plainRich(row.assessment||row.summary||'')}</p>${row.practical?`<div class="life-tip"><strong>이렇게 활용해 보세요</strong><small>${plainRich(row.practical)}</small></div>`:''}</article>`).join('')}</div>`:''}<button class="evidence-link-button" type="button" data-open-evidence>이 내용의 해석 근거 보기 →</button>`}
  function renderProfile(){const r=state.result,f=r.facts||{},p=r.profile_local||{},overview=p.overview||p.summary||{},name=r.profile?.name||'나',overviewText=text(overview)||text(p.personality)||'확인된 출생정보를 바탕으로 나의 성향과 생활 방식을 정리했습니다.',domainCards=Object.keys(DOMAIN_META).map(key=>domainCardHtml(key,p)).join('');$('#page-profile').innerHTML=`<div class="page-shell">${section('내 사주 구성 한눈에',`${reportNatalChart(f,p.chart_detail||{})}${elementOverview(p,f)}<div class="evidence-move-note"><div><strong>신살·길성과 계산 근거도 이어서 볼 수 있어요</strong><p>각 이름의 뜻, 확인된 자리, 오행·십성의 계산 근거는 ‘해석 근거’에서 풀어서 설명합니다.</p></div><button type="button" data-open-evidence>해석 근거 보기 →</button></div>`,'natal-dashboard top-natal-dashboard')}<section class="hero-summary profile-hero card text-only-profile-hero"><div class="profile-hero-copy"><span class="eyebrow">MY SAJU REPORT</span><h2>${esc(name)}님의 성향과 흐름을<span>한눈에 정리했어요</span></h2><div class="profile-summary-copy">${readableEmphasisParagraphs(overviewText,{plain:true,chunk:2,limit:1})}</div><span class="plain-language-badge"><i>${cuteIcon('bunny')}</i>핵심부터 편하게 읽어보세요</span></div></section>${section('먼저 읽는 나의 핵심',`<p class="section-guide">실제 생활에서 반복되기 쉬운 모습을 네 가지로 먼저 정리했어요.</p>${profileKeyPointBoard(p.key_points)}`,'plain-core-section')}${section('생활 속의 나를 6가지로 보기',`<p class="section-guide">궁금한 카테고리를 누르면 성향과 활용 방법을 차례로 확인할 수 있어요.</p><div class="life-domain-grid">${domainCards}</div><div id="profileDomainDetail" class="domain-detail life-domain-detail"><p>카테고리를 선택하면 자세한 설명이 열립니다.</p></div>`,'life-category-section')}</div>`;const buttons=$$('[data-domain]',$('#page-profile'));buttons.forEach(b=>b.onclick=()=>{const panel=$('#profileDomainDetail'),key=b.dataset.domain;panel.innerHTML=profileDomainDetail(key,p[key],p);$$('[data-domain]',$('#page-profile')).forEach(x=>x.closest('.life-domain-card').classList.toggle('active',x===b));$('[data-open-evidence]',panel)?.addEventListener('click',()=>switchPage('details'))});$$('[data-open-evidence]',$('#page-profile')).forEach(b=>b.addEventListener('click',()=>switchPage('details')));buttons[0]?.click()}
  function periodDomainGrid(domains={}){const labels={career:'일·커리어',wealth:'돈·생활',relationships:'사람 관계',romance:'연애',study:'배움'},tones={career:'blue',wealth:'gold',relationships:'mint',romance:'pink',study:'violet'};return `<div class="period-domain-grid">${Object.entries(labels).filter(([k])=>text(domains[k])).map(([k,label])=>`<div class="${tones[k]}"><strong>${label}</strong><p>${emphasisRich(domains[k],{plain:true})}</p></div>`).join('')}</div>`}
