  function fortuneCard(x,label){const icon=label==='올해의 흐름'?'rainbow':label==='이번 달'?'moon':'sun',pillar=String(x.pillar||''),summary=teaser(text(x)||'아직 확인된 내용이 없습니다.'),focus=text(x.focus)||summary,keywords=list(x.keywords).filter(value=>text(value)!==focus).slice(0,2);return `<article class="fortune-card"><header class="fortune-card-head"><div class="fortune-card-title"><span class="fortune-cute-icon">${cuteIcon(icon)}</span><div><h3>${label}</h3><small>${esc(x.period_scope||x.label||'가까운 흐름')}</small></div></div>${pillar?periodPillarVisual(pillar):''}</header><div class="fortune-focus"><span>이 기간 먼저 볼 것</span><strong>${emphasisRich(focus,{plain:true})}</strong></div><div class="fortune-summary">${readableEmphasisParagraphs(summary,{plain:true,chunk:1})}</div>${keywords.length?tags(keywords):''}<details><summary><span>전체 해설과 생활 영역 보기</span><small>핵심 다음에 천천히 읽어도 좋아요</small></summary><div class="fortune-detail-body"><div class="fortune-full-copy">${readableEmphasisParagraphs(text(x)||'아직 확인된 내용이 없습니다.',{plain:true,chunk:2})}</div>${periodDomainGrid(x.domains||{})}<div class="fortune-detail-groups">${fortuneDetailBlock('활용하기 좋은 방향',x.opportunities,'sprout')}${fortuneDetailBlock('조심해서 볼 점',x.cautions,'cloud')}${fortuneDetailBlock('이렇게 해석한 근거',x.evidence,'book')}</div></div></details></article>`}
  function profileAge(){const p=state.result?.profile||state.profile||{},year=Number(p.year),month=Number(p.month),day=Number(p.day);if(!year)return null;const now=new Date();let age=now.getFullYear()-year;if(now.getMonth()+1<month||(now.getMonth()+1===month&&now.getDate()<day))age-=1;return Math.max(0,age)}
