  function renderFortune(){const f=state.result.fortunes||{};const cards=Object.entries(fortuneLabels).map(([k,label])=>fortuneCard(f[k]||{},label)).join(''),dw=f.daewoon||{},periods=list(dw.periods),currentIndex=activeDaewoonIndex(periods),age=profileAge();$('#page-fortune').innerHTML=`<div class="page-shell">${section('올해·이번 달·오늘',`<p class="notice fortune-guide">${rich(f.guide||'큰 흐름과 가까운 흐름을 나누어 살펴봅니다.')}</p><div class="fortune-grid">${cards}</div>`,'fortune-section')}${section('대운 · 삶의 10년 주기 전체',`<div class="daewoon-intro"><div><span class="eyebrow">10년씩 이어지는 삶의 큰 배경</span><h3>${age===null?'현재 구간을 먼저 확인해 보세요':`현재 만 ${age}세가 들어 있는 구간부터 열어두었어요`}</h3><p>간지 두 글자는 각각의 오행 색으로 나눴어요. 다른 나이 구간을 누르면 아래 해설만 바뀝니다.</p></div><div class="daewoon-state-guide"><span class="current">${cuteIcon('bunny')}지금</span><span class="selected">선택한 구간</span></div></div>${periods.length?`<div class="daewoon-timeline-wrap"><div class="daewoon-timeline" role="tablist" aria-label="대운 10년 주기">${periods.map((row,index)=>daewoonPeriodButton(row,index,currentIndex)).join('')}</div></div><div id="daewoonSelected" class="daewoon-selected" aria-live="polite">${daewoonDetail(periods[currentIndex]||{},currentIndex,true)}</div>`:`<div class="empty-state">${rich(dw.detail||'대운표 자료를 확인하지 못했습니다.')}</div>`}<p class="method-footnote">과거 주기는 당시의 반복 배경을 돌아보는 참고로, 미래 주기는 사건 예측이 아니라 선택과 역할의 큰 방향을 준비하는 참고로 읽습니다.</p>`,'daewoon-section')}</div>`;const buttons=$$('[data-daewoon-index]',$('#page-fortune')),panel=$('#daewoonSelected');buttons.forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.daewoonIndex)||0;buttons.forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-selected',String(active))});panel.innerHTML=daewoonDetail(periods[index]||{},index,index===currentIndex);panel.scrollIntoView({behavior:'smooth',block:'nearest'})}));buttons[currentIndex]?.scrollIntoView({block:'nearest',inline:'center'})}
  function centerActiveDaewoon(){const timeline=$('.daewoon-timeline'),active=$('.daewoon-period-button.active');if(!timeline||!active)return;timeline.scrollTo({left:Math.max(0,active.offsetLeft-(timeline.clientWidth-active.offsetWidth)/2),behavior:'smooth'})}
  function candidateCard(row,mode){const p=row.profile||{},res=row.result||{},axes=list(res.axes).slice(0,2),tone=matrixTone(res.total||0),rank=row.rank||0,kind=mode==='love'?'연인':'친구';return `<article class="candidate-card"><button type="button" data-candidate-mode="${mode}" data-candidate-rank="${rank}" aria-label="${kind} 후보 ${rank||'-'}위, ${Math.round(res.total||0)}점 상세 보기"><div class="candidate-card-top"><span class="rank-badge">${rank||'-'}위</span>${sourceBadge(row)}</div><h3>${p.year}.${String(p.month||0).padStart(2,'0')}.${String(p.day||0).padStart(2,'0')}</h3><p>${p.time_known===false?'출생시간 미상':`${String(p.hour||0).padStart(2,'0')}:${String(p.minute||0).padStart(2,'0')}`} · 만 ${row.age_meta?.age??'—'}세</p><div class="candidate-score ${tone}"><strong>${Math.round(res.total||0)}</strong><span>점</span></div><p class="candidate-label">${esc(res.label||'관계 흐름을 분석했어요.')}</p>${axes.length?`<div class="mini-axis">${axes.map(x=>`<span>${esc(pairAxisMeta(x).short)} ${Math.round(x.score||0)}</span>`).join('')}</div>`:''}</button></article>`}
  function compactNatalRows(facts={},profile={}){const chart=facts?.chart||{},profileRows=Object.fromEntries(list(profile?.chart?.pillars).map(row=>[row.key,row.value])),known=facts?.profile?.time_known??profile?.time_accuracy?.known??true;return [{key:'hour',label:'시주',value:known?(chart.hour_pillar||profileRows.hour):''},{key:'day',label:'일주 · 중심',value:chart.day_pillar||profileRows.day},{key:'month',label:'월주',value:chart.month_pillar||profileRows.month},{key:'year',label:'연주',value:chart.year_pillar||profileRows.year}]}
