  function showAutoCandidate(mode,rank){const row=list(state.result.auto_matches?.[mode]).find(x=>String(x.rank)===String(rank));if(!row)return;state.selectedCandidate=row;const res=row.result||{},key=row.candidate_key||'',reports=state.result.pair_reports||{},report=reports[`${mode}:${key}`]||reports[`${mode}:${row.rank}`]||{},analysis=report.analysis||{};$$('[data-candidate-rank]',$('#page-auto')).forEach(x=>x.closest('.candidate-card').classList.toggle('active',x.dataset.candidateMode===mode&&String(x.dataset.candidateRank)===String(rank)));$('#autoCandidateDetail').innerHTML=`<div class="selected-candidate-head"><div><span class="eyebrow">선택한 ${mode==='love'?'연인':'친구'} 후보</span><h3>${row.rank}위 · ${Math.round(res.total||0)}점</h3><div class="candidate-overview-copy">${readableEmphasisParagraphs(text(report.overview)||res.label||'두 사람의 흐름을 비교한 결과입니다.',{chunk:2})}</div></div>${sourceBadge(row)}</div>${compactNatalChart(row.facts,report.person_b||{},'후보 원국')}${candidateStarStrip(row.facts)}<div class="candidate-insight-grid">${readingCard('잘 맞는 이유',report.strengths||res.strengths,'heart','rose')}${readingCard('먼저 조율할 부분',report.risks||res.risks,'cloud','lilac')}${readingCard('편안한 대화 방법',analysis.communication||analysis.communication_daily,'bunny','peach')}${readingCard('역할을 나누는 방법',analysis.role_split||analysis.each_needs,'sparkle','sage')}${readingCard('관계를 오래 쓰는 방법',analysis.long_term||analysis.fit,'sprout','mint')}${readingCard('현실에서 확인할 점',report.reality_checks||analysis.friction_scene||analysis.conflict_repair,'carrot','cream')}</div>${axisCards(report.axes||res.axes,6)}<p class="method-footnote">${esc(sourceDescription(row))}</p>`}
  function recommendationSourceSummary(rows=[]){const data=list(rows),verified=data.filter(row=>sourceState(row).tone==='verified').length,calculated=data.length-verified;return `<div class="recommendation-source-summary"><span><b>${verified}</b>명 · 세부 자료까지 확인</span><span><b>${calculated}</b>명 · 원국 계산 완료</span><small>두 상태 모두 연·월·일·시 원국과 오행 계산은 끝났어요. 차이는 외부 보조자료의 추가 확인 범위입니다.</small></div>`}
  function recommendationBlock(rows,mode){const title=mode==='love'?'연인 TOP 10':'친구 TOP 10',count=list(rows).length;return `<section class="recommendation-block"><div class="recommendation-heading"><div><span class="eyebrow">${mode==='love'?'LOVE MATCH':'FRIEND MATCH'}</span><h3>${title}</h3></div><strong>${count}/10</strong></div>${count?`${recommendationSourceSummary(rows)}<div class="candidate-grid">${list(rows).map(x=>candidateCard(x,mode)).join('')}</div>`:`<div class="empty-state">이 유형의 후보를 아직 만들지 않았어요.</div>`}</section>`}
  function renderAuto(){const a=state.result.auto_matches||{},love=list(a.love),friend=list(a.friend),hasRows=love.length||friend.length,range=a.search_range||{},rangeRule=text(range.rule).replace('세부 원국 확인 후보를 우선하며, 확인 실패로 순위가 부족하면 로컬 원국 기반 예비 후보로 TOP 10을 채웁니다.','외부 세부자료까지 확인된 후보를 우선하며, 나머지는 계산이 완료된 원국에서 확인 가능한 항목만 반영해 TOP 10을 채웁니다.');$('#page-auto').innerHTML=`<div class="page-shell">${section('잘 맞는 사람 TOP 10',hasRows?`<div class="recommendation-guide"><p>연인과 친구를 따로 계산하고, 같은 출생연도에서는 가장 높은 후보 한 명만 남겼어요.</p><small>${esc(range.start_year&&range.end_year?`${range.start_year}~${range.end_year}년생 범위 · ${rangeRule}`:rangeRule||'점수와 세부 축을 함께 비교해 주세요.')}</small></div>${recommendationBlock(love,'love')}${recommendationBlock(friend,'friend')}<div id="autoCandidateDetail" class="domain-detail candidate-detail"><p>후보 카드를 누르면 궁합의 강점, 조율점, 세부 점수 근거까지 보여드려요.</p></div>`:`<div class="empty-state">첫 분석에서 ‘잘 맞는 사람 찾기’를 선택하면 연인·친구 TOP10을 볼 수 있어요.</div>`)}</div>`;$$('[data-candidate-rank]',$('#page-auto')).forEach(b=>b.onclick=()=>showAutoCandidate(b.dataset.candidateMode,b.dataset.candidateRank));if(love.length)showAutoCandidate('love',love[0].rank)}
  function item(label,value){const meta=label.includes('맞는')||label.includes('원하는')?['heart','rose']:label.includes('조율')||label.includes('갈등')||label.includes('엇갈')?['cloud','lilac']:label.includes('대화')||label.includes('표현')?['bunny','peach']:label.includes('역할')||label.includes('생활')?['sparkle','sage']:label.includes('돈')?['carrot','cream']:['sprout','mint'];return readingCard(label,value,meta[0],meta[1])}
