  function targetProfileDomains(profile={},subjectName='상대'){return `<div class="target-domain-grid">${Object.entries(DOMAIN_META).map(([key,meta])=>{const value=text(profile[key]),summary=teaser(value||'확인 가능한 내용을 정리하고 있습니다.'),title=key==='personality'?`${honorificName(subjectName)}의 기본 성향`:meta.title;return `<article class="target-domain-card ${meta.tone}"><div><span>${cuteIcon(meta.icon)}</span><h3>${esc(title)}</h3></div><p>${emphasisRich(summary,{plain:true,subject:subjectName})}</p>${value&&value!==summary?`<details><summary>자세한 해설 보기</summary><div>${readableEmphasisParagraphs(value,{plain:true,chunk:2,subject:subjectName})}</div></details>`:''}</article>`}).join('')}</div>`}
