  function relationshipStyleCard(person,name,{includeRomance=false,label='관계 방식'}={}){const relationship=text(person?.relationships)||text(person?.personality)||text(person?.overview)||'관계에서 중요하게 여기는 기준을 확인합니다.',parts=relationship.split(/(?<=[.!?。])\s+/).filter(Boolean),romanceScenes=includeRomance?[{title:'호감을 표현할 때',row:relationshipDimension(person,['호감과 애정 표현'])},{title:'관계를 결정할 때',row:relationshipDimension(person,['마음이 실제 관계로 이어지는 방식'])},{title:'갈등이 생겼을 때',row:relationshipDimension(person,['갈등이 생겼을 때'])}]:[],scenes=romanceScenes.length?romanceScenes.map((scene,index)=>({title:scene.title,copy:text(scene.row.assessment)||parts[index]||relationship})):[{title:'가까워질 때 편한 조건',copy:parts[0]||relationship},{title:'오래 편하게 지내는 기준',copy:parts[1]||parts[0]||relationship},{title:'서운함이 쌓이기 쉬운 장면',copy:parts[2]||parts.at(-1)||relationship}];return `<article class="person-card relationship-style-card"><span class="eyebrow">${esc(label)}</span><h3>${esc(honorificName(name))}</h3><div class="relationship-scene-list">${scenes.map((scene,index)=>`<section class="relationship-scene"><span>${String(index+1).padStart(2,'0')}</span><div><strong>${esc(scene.title)}</strong><p>${emphasisRich(scene.copy,{plain:true,limit:3,subject:name})}</p></div></section>`).join('')}</div></article>`}
  function pairAxisStories(axes=[],direction='high'){const sorted=[...list(axes)].sort((a,b)=>Number(b.score||0)-Number(a.score||0)),rows=(direction==='high'?sorted:sorted.reverse()).slice(0,2);return rows.map(row=>{const meta=pairAxisMeta(row),score=Math.round(Number(row.score)||0),copy=direction==='high'?meta.strength:meta.caution;return `**${meta.label} · ${score}점**\n${copy} ${meta.action}`})}
