  function initBunnyCursor(){const cursor=$('#bunnyCursor'),fine=matchMedia('(pointer:fine)');if(!cursor||!fine.matches)return;let boingTimer,scrollFrame,lastX=-80,lastY=-80;const interactive='a,button,input,textarea,select,summary,[role="button"],.option-card,[data-open-birth-picker],[data-page]',syncInteractive=target=>cursor.classList.toggle('is-interactive',target instanceof Element&&!!target.closest(interactive)),syncAtPointer=()=>syncInteractive(document.elementFromPoint(lastX,lastY));document.addEventListener('pointermove',e=>{lastX=e.clientX;lastY=e.clientY;cursor.style.left=`${lastX}px`;cursor.style.top=`${lastY}px`;cursor.classList.add('is-visible');syncInteractive(e.target)},{passive:true});document.addEventListener('scroll',()=>{cancelAnimationFrame(scrollFrame);scrollFrame=requestAnimationFrame(syncAtPointer)},{passive:true,capture:true});new MutationObserver(syncAtPointer).observe(document.body,{attributes:true,attributeFilter:['class']});document.addEventListener('pointerdown',()=>{cursor.classList.remove('is-boing');void cursor.offsetWidth;cursor.classList.add('is-boing');clearTimeout(boingTimer);boingTimer=setTimeout(()=>cursor.classList.remove('is-boing'),560)},{passive:true});document.addEventListener('pointerleave',()=>cursor.classList.remove('is-visible'));window.addEventListener('blur',()=>cursor.classList.remove('is-visible'))}
  function initScrollTopButton(){const button=$('#scrollTopButton'),workspace=$('#workspace');if(!button||!workspace)return;let frame=0;const sync=()=>{frame=0;const visible=!workspace.classList.contains('hidden')&&window.scrollY>520;button.classList.toggle('visible',visible);button.setAttribute('aria-hidden',String(!visible));button.tabIndex=visible?0:-1},schedule=()=>{if(!frame)frame=requestAnimationFrame(sync)};button.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}));window.addEventListener('scroll',schedule,{passive:true});new MutationObserver(schedule).observe(workspace,{attributes:true,attributeFilter:['class']});sync()}
