  function init(){initBunnyCursor();initScrollTopButton();bindBirthPickers();bindTimeUnknown();bindCalendarControls();bindCountryControls();$('#introStartButton').onclick=startFromIntro;$('#inputBackButton').onclick=returnFromInput;$('#profileForm').onsubmit=submitInitial;$$('.option-card input').forEach(x=>x.onchange=updateOptions);$$('[data-birth-text],[data-time-text]').forEach(x=>x.addEventListener('blur',updateEstimate));$('#quickTestFixtureButton')?.addEventListener('click',applyTestFixture);$('#cancelAnalysisButton').onclick=cancelActiveRequest;$('#resetButton').onclick=()=>showInputScreen({fromReport:true});$('#printButton').onclick=printReport;$$('.nav-button').forEach(x=>x.onclick=()=>switchPage(x.dataset.page));loadCountries();updateOptions();setInputBackMode(false)}
